INSERT IGNORE INTO `appr_instance` (`id`, `template_id`, `template_code`, `template_version`, `biz_type`, `biz_name`, `biz_id`, `subject_id`, `biz_id_kind`, `biz_no`, `appr_no`, `title`, `applicant_id`, `applicant_name`, `applicant_org_id`, `org_path`, `form_data`, `snapshot`, `table_bindings`, `page_version`, `status`, `current_step`, `total_step`, `callback_status`, `callback_url`, `finished_at`, `deleted`, `created_at`, `updated_at`, `urge_count`, `last_urge_at`) VALUES (2118926088937660418,9002,'ehr_regularize_default',2,'ehr.regularize','转正审批','2118926088866349057','2118873840320729090','DOC','A0164','SP-20261107-000052','转正审批 · 测试',2118896521678127106,'测试',2400000000000000001,'晨星科技集团 / 星辰科技（西安）有限公司 / 研发部 / 基础平台项目','{\"employeeId\":\"2118873840320729090\",\"empNo\":\"A0164\",\"name\":\"测试\",\"orgPath\":\"晨星科技集团 / 星辰科技（西安）有限公司 / 研发部 / 基础平台项目\",\"position\":\"高级开发工程师\",\"hireDate\":\"2026-11-07\",\"probationMonths\":3,\"expectedRegularizeDate\":\"2027-02-07\",\"regularizeDate\":\"2027-02-07\",\"selfReview\":\"在为期三个月的试用期内，我快速熟悉了团队的技术栈与业务架构，严格遵守公司各项规章制度。工作上保持积极主动，按时高质量完成了分配的开发任务，并主动参与代码审查。与团队同事沟通顺畅、协作融洽，能够快速融入研发团队氛围。同时，我也在持续学习基础平台相关的新技术，不断优化代码质量。整体而言，我已完全适应目前的工作节奏，具备正式员工的履职能力，期待能继续与团队共同成长。\",\"workSummary\":\"1.核心业务开发：主导并完成了基础平台项目中“XX模块”的微服务重构，将接口响应时间优化了30%，有效提升了系统整体吞吐量。\\n2.代码质量提升：在负责的模块中引入了单元测试覆盖，使核心代码测试覆盖率从0提升至75%，大幅降低了线上回归测试的成本与风险。\\n3.技术文档沉淀：梳理并输出了《基础平台接口规范文档》与《项目本地开发环境搭建指南》，有效降低了新同事的入职学习成本。\\n4.日常需求交付：高效完成日常业务需求共计15个，Bug修复率100%，保证了负责模块的平稳上线运行，期间未出现任何严重生产事故。\",\"reason\":\"经过三个月的试用期，我对公司的企业文化、研发流程以及基础平台项目的业务逻辑已有了深入的理解。在专业技能上，我已能独立承担核心模块的设计与开发任务，并取得了切实的业绩成果。在团队协作方面，我与产品、测试及前端同事配合默契，能够高效推进项目落地。我认为自己已经完全具备了一名正式高级开发工程师所需的各项能力与职业素养，因此特申请转正。希望转正后能承担更多具有挑战性的工作，为公司创造更大的价值。\",\"nextPlan\":\"1.短期目标（1-3个月）：深入攻克基础平台底层架构的痛点，完成剩余历史债务的重构工作，进一步提升系统的高可用性与稳定性。\\n2.中期目标（3-6个月）：计划引入并落地新的自动化CI/CD流程，缩短项目构建与发布周期；同时探索并实践相关前沿技术（如容器化部署、性能监控等）在团队内的应用。\\n3.长期目标：沉淀技术积累，分享技术心得，尝试指导新入职的初级开发同学，努力成为团队内的技术骨干，与团队共同实现业务与技术架构的突破。\",\"probationText\":\"3 个月 · 预计 2027-02-07 转正\",\"submitter\":\"测试\"}','{\"version\":2,\"steps\":[{\"seq\":1,\"name\":\"用人部门审批\",\"conditionExpr\":\"\",\"rejectAction\":\"END\",\"branchPath\":\"\",\"depth\":0,\"uiKind\":\"APPROVER\",\"nodes\":[{\"nodeId\":2118015340128403458,\"seq\":1,\"name\":\"部门负责人\",\"conditionExpr\":\"\",\"isFallback\":false,\"approveMode\":\"ANY\",\"allowSelf\":0,\"skipSame\":1,\"onEmpty\":\"BLOCK\",\"approvers\":[{\"type\":\"ORG_LEADER\",\"levelOffset\":0,\"toRoot\":false}]}]},{\"seq\":2,\"name\":\"人事主管审批\",\"conditionExpr\":\"\",\"rejectAction\":\"END\",\"branchPath\":\"\",\"depth\":0,\"uiKind\":\"APPROVER\",\"nodes\":[{\"nodeId\":2118015340128403460,\"seq\":1,\"name\":\"人事主管\",\"conditionExpr\":\"\",\"isFallback\":false,\"approveMode\":\"ANY\",\"allowSelf\":0,\"skipSame\":1,\"onEmpty\":\"BLOCK\",\"approvers\":[{\"type\":\"ORG_LEADER_BY_NAME\",\"code\":\"人力资源中心\",\"levelOffset\":0,\"toRoot\":false}]}]}]}','{\"appCode\":\"ehr\",\"subjectKey\":\"employeeId\",\"tables\":[{\"table\":\"ehr_employee\",\"label\":\"员工档案\",\"main\":true,\"oneToOne\":false,\"mode\":\"MAIN_ROW\"},{\"table\":\"ehr_regularize_apply\",\"fk\":\"employee_id\",\"label\":\"转正申请\",\"main\":false,\"oneToOne\":false,\"mode\":\"BIZ_ROW\"}]}',NULL,3,1,2,2,'http://127.0.0.1:9006/internal/ehr/approval-callback','2026-11-07 12:39:09',0,'2026-11-07 12:38:42','2026-11-07 14:10:08',0,NULL);
